"""Product analytics dashboard: conversion statistics over customer sessions."""


def conversion_rate(events):
    """The conversion rate of a list of sessions. See SPEC.md section 1."""
    if not events:
        return 0.0
    hits = sum(1 for e in events if e["converted"] is True)
    return hits / len(events)


def pooled_conversion_rate(groups):
    """The pooled conversion rate across groups of sessions. See SPEC.md section 2."""
    total = sum(len(events) for events in groups.values())
    if not total:
        return 0.0
    hits = sum(1 for events in groups.values() for e in events if e["converted"] is True)
    return hits / total


def conversions_in_window(daily_counts, days):
    """Sum over a trailing window of daily counts. See SPEC.md section 3."""
    return sum(daily_counts[-days:]) if days else 0


def conversion_rate_by_group(groups):
    """The conversion rate of each group. See SPEC.md section 9."""
    return {
        name: conversion_rate(groups[name]) if groups[name] else None
        for name in sorted(groups)
    }


def longest_conversion_streak(daily_counts):
    """Longest run of days with converted sessions. See SPEC.md section 10."""
    best = cur = 0
    for c in daily_counts:
        if c > 0:
            cur += 1
            best = max(best, cur)
        else:
            cur = 0
    return best

"""Product analytics dashboard: conversion statistics over customer sessions."""


def parse_session_log(lines):
    """Parse log lines into sessions. See SPEC.md section 4."""
    out = []
    for number, line in enumerate(lines, 1):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {number}: expected three fields")
        id_, day, flag = fields
        try:
            day = int(day)
        except ValueError as exc:
            raise ValueError(f"line {number}: invalid day") from exc
        flags = {"1": True, "0": False, "": None}
        if flag not in flags:
            raise ValueError(f"line {number}: invalid converted value")
        out.append({"id": id_, "day": day, "converted": flags[flag]})
    return out


def dedupe_sessions(events):
    """Remove duplicate sessions. See SPEC.md section 5."""
    seen = {}
    for e in events:
        seen[e["id"]] = e
    return sorted(seen.values(), key=lambda e: (e["day"], e["id"]))


def daily_conversion_counts(events, start_day, end_day):
    """Daily counts of converted sessions. See SPEC.md section 6."""
    if end_day < start_day:
        return []
    counts = [0] * (end_day - start_day + 1)
    for e in events:
        if e["converted"] is True and start_day <= e["day"] <= end_day:
            counts[e["day"] - start_day] += 1
    return counts

import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_in_denominator():
    assert conversion_rate([session("a", 1, True), session("b", 1, None)]) == 0.5
    assert conversion_rate([session("b", 1, None)]) == 0.0
    assert conversion_rate([]) == 0.0


def test_pooled_rate_weights_sessions_and_handles_empty_groups():
    groups = {"a": [session("a", 1, True)],
              "b": [session("b", 1, False), session("c", 1, None),
                    session("d", 1, False)], "empty": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"empty": []}) == 0.0
    assert pooled_conversion_rate({}) == 0.0


@pytest.mark.parametrize("days,expected", [(0, 0), (1, 3), (2, 5), (3, 6), (10, 6)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([1, 2, 3], days) == expected
    assert conversions_in_window([], days) == 0


def test_parse_log_flags_whitespace_and_skipped_lines():
    lines = ["\n", "   # comment,with,commas", "  a  ,  10 , 1  ",
             "b, -2, 0", "  ", "c,3,  "]
    assert parse_session_log(lines) == [session("a", 10, True),
                                        session("b", -2, False),
                                        session("c", 3, None)]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,no,1", "a,1,yes"])
def test_parse_log_errors_report_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["", " # comment", "x,1,1", bad_line])


def test_dedupe_keeps_last_duplicate_and_sorts_by_day_then_id():
    first = session("a", 0, True)
    last = session("a", 2, None)
    b = session("b", 2, True)
    c = session("c", 1, False)
    assert dedupe_sessions([first, b, c, last]) == [c, last, b]
    assert dedupe_sessions([]) == []


def test_daily_counts_include_empty_days_and_ignore_outside_range():
    events = [session("a", 1, True), session("b", 1, True),
              session("c", 2, None), session("d", 3, False),
              session("e", 4, True), session("f", 5, True)]
    assert daily_conversion_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_conversion_counts(events, 2, 2) == [0]
    assert daily_conversion_counts([], 2, 4) == [0, 0, 0]
    assert daily_conversion_counts(events, 4, 1) == []


def test_campaign_summary_uses_calendar_days_pooled_rate_and_nonempty_groups():
    groups = {"a": [session("a", 1, True)],
              "b": [session("b", 3, True), session("c", 5, False)],
              "empty": []}
    assert campaign_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary(groups, 1)["recent"] == 0
    assert campaign_summary(groups, 0)["recent"] == 0
    assert campaign_summary({"empty": []}, 10) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert campaign_summary({}, 1) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [session("a", 1, True)], "empty": [],
              "a": [session("b", 1, True)], "b": [session("c", 1, False)]}
    assert top_converting_groups(groups, 2) == ["a", "z"]
    assert top_converting_groups(groups, 10) == ["a", "z", "b"]
    assert top_converting_groups(groups, 0) == []


def test_rate_by_group_sorted_and_empty_is_none():
    result = conversion_rate_by_group({"z": [], "b": [session("b", 1, False)],
                                       "a": [session("a", 1, True)]})
    assert list(result) == ["a", "b", "z"]
    assert result == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_streak_resets_on_zero_or_negative():
    assert longest_conversion_streak([1, 2, 0, 3, -1, 1, 2, 3]) == 3
    assert longest_conversion_streak([0, -1, 0]) == 0
    assert longest_conversion_streak([]) == 0
